    "전화번호가 자동으로 입력되었습니다. '확인'을 눌러 다음 단계로 넘어가 주세요.": "Nomor telepon telah otomatis terisi. Tekan 'Konfirmasi' untuk melanjutkan ke langkah berikutnya.",
