    "비밀번호 설정 후 '확인'을 눌러주세요.": "Setelah mengatur kata sandi, tekan 'Konfirmasi'.",
    "비밀번호를 모두 입력하셨다면 '확인'을 눌러주세요.": "Jika Anda telah memasukkan semua kata sandi, tekan 'Konfirmasi'.",
