    "은행 앱에서 1원 입금 내역을 보면 'SKT또는 LGU또는 KT' 뒤에 숫자 3자리가 적혀 있습니다.": "หากคุณดูประวัติการฝากเงิน 1 วอนในแอปธนาคารของคุณ จะมีตัวเลข 3 หลักอยู่หลัง 'SKT หรือ LGU หรือ KT'",
