    "이용 중인 통신사를 선택해 주세요. (알뜰폰은 하단 탭 확인)": "请选择您正在使用的运营商。（廉价手机请查看底部选项卡）",
    "본인 휴대폰 번호를 입력해 주세요.": "请输入您的手机号码。",
