    "정보 입력 후 '1원 송금하기'를 눌러주세요.": "输入信息后，请点击'汇款1韩元'。",
    "입금자명 '카카오' 뒤의 숫자 3자리를 입력해 주세요.": "请输入存款人姓名‘Kakao’后面的3位数字。",
    "숫자 3자리 입력 후 '확인'을 눌러주세요.": "输入3位数字后，请点击'确认'。",
    "은행 앱의 입금 내역에서 '카카오' 뒤의 숫자 3자리를 확인해 주세요.": "请在银行App的存款记录中确认'Kakao'后面的3位数字。",
    "은행 앱에서 확인하신 숫자 3자리를 입력해 주세요.": "请在银行应用程序中输入您确认的3位数字。",
    "입력 후 하단의 '확인' 버튼을 눌러 다음으로 진행해 주세요.": "输入后，请点击下方‘确认’按钮继续。",
