    "본인 통신사에 맞는 PASS 앱을 설치해 주세요": "请安装与您的运营商匹配的PASS应用程序",
    "이용 중인 통신사의 PASS 앱을 설치해 주세요": "请安装您正在使用的运营商的PASS App。",
