    "'인증번호요청' 버튼을 누른 후 문자로 받은 번호를 입력해 주세요": "点击“请求验证码”按钮后，请输入通过短信收到的号码",
    "정보 입력 후 '다음' 버튼을 눌러주세요": "输入信息后，请点击'下一步'按钮",
    "문자로 받은 인증번호 6자리를 입력해 주세요": "请输入短信收到的6位验证码",
