    "본인이 사용 중인 은행을 목록에서 선택해 주세요": "请从列表中选择您正在使用的银行",
    "본인 명의의 계좌번호를 하이픈(-) 없이 숫자만 입력해 주세요": "请输入本人名下的银行账号，仅输入数字，不包含连字符(-)。",
