    "GUIDE_CONGRATS": "🎉 Binabati kita 🎉\nAng iyong sertipiko ay naisyu na!\n\nBumalik na ngayon sa screen na nangangailangan ng sertipiko (halimbawa, Freet self-activation) at ipagpatuloy ang iyong pag-verify ng pagkakakilanlan.",
